"""Exact endomorphism orders and arithmetic centralizers of finite Z groups.

All linear algebra, lattice saturation, multiplication and certificates are
exact. Complete split-rational unit groups use a finite lattice stabilizer,
including glued isotypic modules. Other certified normalizers and definite
norm forms supply further complete branches; a budget is never a proof.
"""

from itertools import product, combinations
from math import gcd, isqrt, lcm, prod
import crystkit_browser as c
import crystkit_extensions as ext
import integral_normalizer as norm


def _sp():
    import sympy as sp
    return sp


def _vec(a):
    return _sp().Matrix(list(a))


def _clear(a):
    sp = _sp()
    denominator = lcm(*(int(x.q) for x in a)) if len(a) else 1
    return sp.Matrix(a.rows, a.cols, [int(x*denominator) for x in a])


def _kernel_equations(a):
    """Equivalent short rational row system before an integer Smith kernel."""
    sp = _sp()
    rows = list(dict.fromkeys(tuple(a.row(i)) for i in range(a.rows) if any(a.row(i))))
    if not rows:
        return sp.zeros(0, a.cols)
    reduced = sp.Matrix(rows)
    if reduced.rows > reduced.cols:
        reduced = sp.Matrix.vstack(*reduced.rowspace())
    return _clear(reduced)


def _lattice_basis(a):
    """Column basis of the rational lattice generated by the columns of a."""
    from sympy.matrices.normalforms import hermite_normal_form
    denominator = lcm(*(int(x.q) for x in a)) if len(a) else 1
    return hermite_normal_form(_clear(a))/denominator


def _saturated_subspace(a):
    sp = _sp()
    equations = sp.Matrix.hstack(*a.T.nullspace()).T if a.T.nullspace() else sp.zeros(0, a.rows)
    return norm._integer_kernel(_clear(equations))


def _coordinates(basis, a):
    vectors = _sp().Matrix.hstack(*(_vec(b) for b in basis))
    return (vectors.T*vectors).inv()*vectors.T*_vec(a)


def intertwiner_basis(left_generators, right_generators, integral=False):
    """Basis X of X*A=B*X; rectangular modules and saturated Z basis supported."""
    sp = _sp()
    left = [sp.Matrix(a) for a in left_generators]
    right = [sp.Matrix(a) for a in right_generators]
    if not left or len(left) != len(right):
        raise ValueError("Supply matching nonempty generator lists")
    rows, cols = right[0].rows, left[0].rows
    variables = sp.symbols(f"x0:{rows*cols}")
    x = sp.Matrix(rows, cols, variables)
    equations = []
    for a, b in zip(left, right):
        equations.extend(x*a-b*x)
    system, _ = sp.linear_eq_to_matrix(equations, variables)
    if integral:
        vectors = norm._integer_kernel(_kernel_equations(system))
    else:
        null = system.nullspace()
        vectors = sp.Matrix.hstack(*null) if null else sp.zeros(rows*cols, 0)
    return [sp.Matrix(rows, cols, list(vectors[:, j])) for j in range(vectors.cols)]


def commutant_basis(generators, integral=True):
    return intertwiner_basis(generators, generators, integral)


def _center_basis(basis):
    sp = _sp()
    variables = sp.symbols(f"z0:{len(basis)}")
    a = sum((x*b for x, b in zip(variables, basis)), sp.zeros(basis[0].rows))
    equations = []
    for b in basis:
        equations.extend(a*b-b*a)
    system, _ = sp.linear_eq_to_matrix(equations, variables)
    coefficients = norm._integer_kernel(_kernel_equations(system))
    return [sum((coefficients[i, j]*b for i, b in enumerate(basis)), sp.zeros(a.rows)) for j in range(coefficients.cols)]


def _poly_matrix(poly, a):
    sp = _sp()
    result = sp.zeros(a.rows)
    for coefficient in poly.all_coeffs():
        result = result*a+coefficient*sp.eye(a.rows)
    return result


def center_decomposition(basis):
    """Primitive central idempotents via a separating element and rational CRT."""
    sp = _sp()
    center = _center_basis(basis)
    rank, d = len(center), basis[0].rows
    x = sp.Symbol("x")
    bound = (rank-1)*rank*(rank-1)//2+1
    for t in range(1, bound+1):
        a = sum((t**i*b for i, b in enumerate(center)), sp.zeros(d))
        polynomial = sp.Poly(a.charpoly(x).as_expr(), x).sqf_part()
        if polynomial.degree() == rank:
            break
    else:
        raise ArithmeticError("The finite-group commutant center failed separability")
    pieces = []
    for factor, _ in sp.factor_list(polynomial.as_expr(), x)[1]:
        f = sp.Poly(factor, x, domain=sp.QQ)
        q = polynomial.exquo(f)
        projector_polynomial = (q*sp.invert(q, f)).rem(polynomial)
        projector = _poly_matrix(projector_polynomial, a)
        if projector*projector != projector:
            raise ArithmeticError("Central CRT idempotent failed exact verification")
        lattice = norm._integer_kernel(_clear(sp.eye(d)-projector))
        local_commutant_rank = sp.Matrix.hstack(*(_vec(projector*b) for b in basis)).rank()
        pieces.append({"fieldDegree": f.degree(), "fieldPolynomial": f.as_expr(),
                       "projector": projector, "basis": lattice,
                       "dimension": lattice.cols, "commutantDimension": local_commutant_rank})
    if sum((p["projector"] for p in pieces), sp.zeros(d)) != sp.eye(d):
        raise ArithmeticError("Central idempotents do not sum to one")
    return {"centerBasis": center, "centerDimension": rank, "primitiveElement": a,
            "minimalPolynomial": polynomial.as_expr(), "components": pieces}


def order_data(group, include_structure=True, expand_norm=False):
    sp = _sp()
    generators = [c._sympy_matrix(g) for g in ext._choose_generators(group)] or [sp.eye(len(group[0]))]
    basis = commutant_basis(generators)
    center = center_decomposition(basis)
    d, rank = len(group[0]), len(basis)
    variables = sp.symbols(f"u0:{rank}")
    generic = sum((x*b for x, b in zip(variables, basis)), sp.zeros(d))
    if expand_norm and rank > 12:
        raise ValueError("Expanded unit-norm polynomials are limited to order rank 12; the exact determinant representation remains available")
    determinant = sp.factor(generic.det(method="domain-ge")) if rank <= 8 or expand_norm else sp.Determinant(generic)
    result = {"dimension": d, "pointGroupOrder": len(group), "orderRank": rank,
              "orderBasis": [c._from_sympy(b) for b in basis],
              "centerDimension": center["centerDimension"],
              "centerBasis": [c._from_sympy(b) for b in center["centerBasis"]],
              "centerPrimitiveElement": c._from_sympy(center["primitiveElement"]),
              "centerMinimalPolynomial": str(center["minimalPolynomial"]),
              "centerDecomposition": [{"fieldDegree": p["fieldDegree"], "fieldPolynomial": str(p["fieldPolynomial"]),
                  "projector": c._from_sympy(p["projector"]), "latticeBasis": c._from_sympy(p["basis"]),
                  "dimension": p["dimension"], "commutantDimension": p["commutantDimension"]} for p in center["components"]],
              "unitVariables": [str(x) for x in variables], "unitNormPolynomial": str(determinant),
              "unitNormMatrix": [[str(x) for x in generic.row(i)] for i in range(d)],
              "unitEquation": "det(sum(u_i * orderBasis[i])) = +1 or -1, with every u_i an integer",
              "orderComplete": True, "centerDecompositionComplete": True,
              "certificate": "Saturated Smith kernel of all commutator equations; exact integral multiplication; separable rational center and verified primitive CRT idempotents"}
    if include_structure:
        vectors = sp.Matrix.hstack(*(_vec(b) for b in basis))
        inverse = (vectors.T*vectors).inv()*vectors.T
        constants = []
        for a in basis:
            row = []
            for b in basis:
                coefficients = inverse*_vec(a*b)
                if any(x.q != 1 for x in coefficients) or vectors*coefficients != _vec(a*b):
                    raise ArithmeticError("The saturated commutant lattice is not closed under multiplication")
                row.append([int(x) for x in coefficients])
            constants.append(row)
        result["multiplicationConstants"] = constants
        result["identityCoordinates"] = [int(x) for x in inverse*_vec(sp.eye(d))]
    return result, basis, center


def _irreducible_model(group, component, max_trials):
    """Search a rational simple summand, but certify absolutely irreducible Q type."""
    sp = _sp()
    dimension, algebra_dimension = component["dimension"], component["commutantDimension"]
    multiplicity = isqrt(algebra_dimension)
    if component["fieldDegree"] != 1 or multiplicity**2 != algebra_dimension or dimension % multiplicity:
        return None
    r = dimension//multiplicity
    b = component["basis"]
    left_inverse = (b.T*b).inv()*b.T
    point_generators = ext._choose_generators(group) or [group[0]]
    local = [left_inverse*c._sympy_matrix(g)*b for g in point_generators]
    if multiplicity == 1:
        candidates = [sp.eye(dimension)]
    elif r == 1:
        candidates = [sp.eye(dimension)[:, :1]]
    else:
        endomorphisms = commutant_basis(local, integral=False)
        gram = c._sympy_matrix(c.invariant_gram([c._from_sympy(g) for g in local]))
        # A definite division algebra has only scalar self-adjoint elements;
        # do not run a split-matrix search in the quaternion case.
        self_adjoint = [a+gram.inv()*a.T*gram for a in endomorphisms]
        if sp.Matrix.hstack(*(_vec(a) for a in self_adjoint)).rank() == 1:
            return None
        def subspaces():
            attempts = 0
            # Cheap cyclic spans first; arbitrary integral coordinates often
            # already meet a primitive irreducible constituent.
            for j in range(dimension):
                v = sp.eye(dimension)[:, j]
                orbit = sp.Matrix.hstack(*(c._sympy_matrix(g)*b*v for g in group))
                if orbit.rank() == r:
                    yield left_inverse*sp.Matrix.hstack(*orbit.columnspace())
            combinations_seen = set()
            matrices = list(endomorphisms)
            matrices += [a+sign*z for i, a in enumerate(endomorphisms) for z in endomorphisms[i+1:] for sign in (-1, 1)]
            def search_matrices():
                yield from matrices
                for radius in range(1, max_trials+1):
                    for values in product(range(-radius, radius+1), repeat=len(endomorphisms)):
                        if max(map(abs, values)) != radius:
                            continue
                        yield sum((x*a for x, a in zip(values, endomorphisms)), sp.zeros(dimension))
            for a in search_matrices():
                key = tuple(a)
                if key in combinations_seen:
                    continue
                combinations_seen.add(key)
                attempts += 1
                if attempts > max_trials:
                    return
                for factor, _ in sp.factor_list(a.charpoly().as_expr())[1]:
                    polynomial = sp.Poly(factor)
                    if polynomial.degree() == 1:
                        eigenvalue = -polynomial.nth(0)/polynomial.nth(1)
                        null = (a-eigenvalue*sp.eye(dimension)).nullspace()
                        if len(null) == r:
                            yield sp.Matrix.hstack(*null)
        candidates = subspaces()
    for candidate in candidates:
        saturated = _saturated_subspace(b*candidate)
        left = (saturated.T*saturated).inv()*saturated.T
        model = [left*c._sympy_matrix(g)*saturated for g in point_generators]
        if len(commutant_basis(model, integral=False)) != 1:
            continue
        if any(any(x.q != 1 for x in g) for g in model):
            raise ArithmeticError("Saturated rational constituent is not an integral G lattice")
        hom = intertwiner_basis(model, [c._sympy_matrix(g) for g in point_generators])
        if len(hom) != multiplicity:
            continue
        tensor = sp.Matrix.hstack(*hom)
        if tensor.rank() != dimension:
            continue
        return {"basis": tensor, "irreducibleDimension": r, "multiplicity": multiplicity,
                "modelGenerators": model, "pointGenerators": point_generators,
                "modelLatticeBasis": saturated}
    return None


def split_decomposition(group, max_trials=2000, center=None):
    """Verified rational tensor decomposition for split-rational semisimple type.

    None is inconclusive/unsupported. Every returned model is integral and has
    rational commutant Q. Columns are ordered by copy, then irreducible index.
    """
    sp = _sp()
    characters = norm.character_decomposition(group)
    if characters is not None:
        point_generators = ext._choose_generators(group) or [group[0]]
        components, start = [], 0
        for block in characters:
            b = block["basis"]
            vector = b[:, 0]
            nonzero = next(i for i in range(b.rows) if vector[i])
            model = [sp.Matrix([[(c._sympy_matrix(g)*vector)[nonzero]/vector[nonzero]]]) for g in point_generators]
            components.append({"basis": b, "start": start, "dimension": b.cols,
                               "irreducibleDimension": 1, "multiplicity": b.cols,
                               "modelGenerators": model, "pointGenerators": point_generators,
                               "modelLatticeBasis": vector})
            start += b.cols
        return {"basis": sp.Matrix.hstack(*(p["basis"] for p in components)),
                "components": components, "pointGenerators": point_generators,
                "complete": True, "certificate": "Exact saturated simultaneous rational sign-character lattices"}
    if center is None:
        generators = [c._sympy_matrix(g) for g in ext._choose_generators(group)] or [sp.eye(len(group[0]))]
        center = center_decomposition(commutant_basis(generators))
    components, start = [], 0
    for piece in center["components"]:
        model = _irreducible_model(group, piece, max_trials)
        if model is None:
            return None
        model["start"] = start
        model["dimension"] = piece["dimension"]
        components.append(model)
        start += piece["dimension"]
    basis = sp.Matrix.hstack(*(p["basis"] for p in components))
    if basis.rows != basis.cols or basis.det() == 0:
        raise ArithmeticError("Rational tensor decomposition does not span the representation")
    inverse = basis.inv()
    point_generators = components[0]["pointGenerators"]
    for k, g in enumerate(point_generators):
        expected = sp.diag(*(p["modelGenerators"][k] for p in components for _ in range(p["multiplicity"])))
        if inverse*c._sympy_matrix(g)*basis != expected:
            raise ArithmeticError("Rational tensor decomposition failed its exact action identity")
    return {"basis": basis, "components": components, "pointGenerators": point_generators,
            "complete": True, "certificate": "Primitive rational central projectors; verified absolutely irreducible integral models; full Hom bases and exact repeated-block identities"}


def projection_lattice_basis(basis, components):
    """Canonical over-lattice from sums of irreducible-coordinate projections."""
    sp = _sp()
    inverse = basis.inv()
    blocks, ambient = [], []
    d = basis.rows
    records = []
    for component in components:
        start = component["start"]
        r, m = component["irreducibleDimension"], component["multiplicity"]
        projections = [inverse[[start+j*r+i for j in range(m)], :] for i in range(r)]
        h = _lattice_basis(sp.Matrix.hstack(*projections))
        if h.shape != (m, m):
            raise ArithmeticError("Multiplicity projection lattice is not full rank")
        blocks.append(sp.kronecker_product(h, sp.eye(r)))
        records.append({"basis": h, "irreducibleDimension": r, "multiplicity": m})
        for g in ext._gl_generators(m):
            ambient.append(norm._embed(sp.kronecker_product(c._sympy_matrix(g), sp.eye(r)), start, d))
    over_basis = basis*sp.diag(*blocks)
    lattice = over_basis.inv()
    if any(x.q != 1 for x in lattice):
        raise ArithmeticError("Projection lattice does not contain the original integer lattice")
    return {"basis": over_basis, "lattice": _lattice_basis(lattice),
            "ambientGenerators": ambient, "projectionLattices": records}


def lattice_orbit_transport(source_lattice, target_lattice, generators,
                            max_orbit=20000, max_generators=100000,
                            stop_on_transport=False):
    """Full finite fixed-index lattice orbit; exact transport and stabilizer."""
    sp = _sp()
    from sympy.matrices.normalforms import hermite_normal_form
    if any(x.q != 1 for x in source_lattice) or (target_lattice is not None and any(x.q != 1 for x in target_lattice)):
        raise ValueError("Finite lattice orbit requires integral full-rank bases")
    source = hermite_normal_form(_clear(source_lattice))
    target = hermite_normal_form(_clear(target_lattice)) if target_lattice is not None else None
    if target is not None and abs(source.det()) != abs(target.det()):
        return {"complete": True, "equivalent": False, "transport": None, "orbitSize": 0, "generators": []}
    matrices = norm._deduplicate(generators)
    states, seen = [(source, sp.eye(source.rows))], {tuple(source): 0}
    inverses, stabilizer, known = [sp.eye(source.rows)], [], set()
    transport = sp.eye(source.rows) if target == source else None
    if transport is not None and stop_on_transport:
        return {"complete": True, "equivalent": True, "transport": transport,
                "orbitSize": 1, "generators": [], "orbitComplete": False}
    for lattice, word in states:
        for a in matrices:
            new_lattice = hermite_normal_form(a*lattice)
            key = tuple(new_lattice)
            new_word = a*word
            norm._entry_limit(new_word)
            if key not in seen:
                if len(states) >= max_orbit:
                    raise c.SearchLimitError("Finite arithmetic lattice orbit exceeded max_orbit; completeness is not established")
                seen[key] = len(states)
                states.append((new_lattice, new_word))
                inverses.append(new_word.inv())
                if target is not None and new_lattice == target:
                    transport = new_word
                    if stop_on_transport:
                        return {"complete": True, "equivalent": True, "transport": transport,
                                "orbitSize": len(states), "generators": [], "orbitComplete": False}
                continue
            generator = inverses[seen[key]]*new_word
            if generator != sp.eye(source.rows) and tuple(generator) not in known:
                if len(stabilizer) >= max_generators:
                    raise c.SearchLimitError("Arithmetic Schreier generator budget exceeded")
                known.add(tuple(generator))
                stabilizer.append(generator)
    return {"complete": True, "equivalent": transport is not None if target is not None else None,
            "transport": transport, "orbitSize": len(states), "generators": stabilizer, "orbitComplete": True}


def labelled_integral_equivalence(left_generators, right_generators,
                                  max_trials=2000, max_orbit=20000,
                                  max_generators=100000, decomposition=None):
    """Decide integral module equivalence with a fixed generator correspondence.

    Complete for a verified split-rational source module; negative answers use
    a full finite lattice orbit, never a bounded coefficient search.
    """
    sp = _sp()
    left = [c._sympy_matrix(c.matrix(g)) for g in left_generators]
    right = [c._sympy_matrix(c.matrix(g)) for g in right_generators]
    if not left or len(left) != len(right) or any(g.shape != left[0].shape for g in right):
        raise ValueError("Integral equivalence requires matching square generator lists")
    if decomposition is None:
        source_group = ext._point_input({"rotations": left_generators})
        decomposition = split_decomposition(source_group, max_trials)
    if decomposition is None:
        quadratic = quadratic_integral_equivalence(left_generators, right_generators,
            max_candidates=max_generators)
        if quadratic is not None:
            return quadratic
        return {"complete": False, "equivalent": None, "conjugator": None,
                "certificate": "A complete split-rational decomposition has not been established"}
    source_basis = decomposition["basis"]
    inverse = source_basis.inv()
    target_blocks = []
    for component in decomposition["components"]:
        start, r, m = component["start"], component["irreducibleDimension"], component["multiplicity"]
        model = [(inverse*g*source_basis)[start:start+r, start:start+r] for g in left]
        hom = intertwiner_basis(model, right)
        if len(hom) != m:
            return {"complete": True, "equivalent": False, "conjugator": None,
                    "certificate": "Exact Hom dimensions exclude rational module equivalence"}
        target_blocks.extend(hom)
    target_basis = sp.Matrix.hstack(*target_blocks)
    if target_basis.shape != source_basis.shape or target_basis.det() == 0:
        return {"complete": True, "equivalent": False, "conjugator": None,
                "certificate": "The exact rational Hom components do not span the target module"}
    source = projection_lattice_basis(source_basis, decomposition["components"])
    target = projection_lattice_basis(target_basis, decomposition["components"])
    orbit = lattice_orbit_transport(source["lattice"], target["lattice"], source["ambientGenerators"],
                                    max_orbit, max_generators, stop_on_transport=True)
    witness = None
    if orbit["equivalent"]:
        witness = target["basis"]*orbit["transport"]*source["basis"].inv()
        if any(x.q != 1 for x in witness) or abs(witness.det()) != 1 or any(witness*a != b*witness for a, b in zip(left, right)):
            raise ArithmeticError("Integral module equivalence witness failed exact verification")
    return {"complete": True, "equivalent": orbit["equivalent"],
            "conjugator": c._from_sympy(witness) if witness is not None else None,
            "orbitSize": orbit["orbitSize"], "orbitComplete": orbit.get("orbitComplete", True),
            "certificate": "Exact split-rational Hom decomposition and intrinsic multiplicity projection lattices; integral intertwiner is equivalent to a finite GL(m,Z) lattice transport; positive witness or exhaustive negative orbit"}


def automorphism_images(group, max_assignments=100000):
    """Exhaust all character-preserving abstract automorphisms of this image."""
    sp = _sp()
    generators = ext._choose_generators(group) or [group[0]]
    signatures = {g: tuple(c._sympy_matrix(g).charpoly().all_coeffs()) for g in group}
    choices = [[g for g in group if signatures[g] == signatures[a]] for a in generators]
    count = prod(len(values) for values in choices)
    if count > max_assignments:
        raise c.SearchLimitError("Finite point-group automorphism assignment count exceeds max_assignments")
    d = len(group[0])
    keys = [tuple(int(x) for row in g for x in row) for g in group]
    ids = {key: i for i, key in enumerate(keys)}
    group_ids = {g: i for i, g in enumerate(group)}
    multiplication = {}
    def multiply(i, j):
        if (i, j) not in multiplication:
            a, b = keys[i], keys[j]
            value = tuple(sum(a[x*d+k]*b[k*d+y] for k in range(d)) for x in range(d) for y in range(d))
            multiplication[i, j] = ids[value]
        return multiplication[i, j]
    generator_ids = [group_ids[g] for g in generators]
    source_products = [[multiply(i, j) for j in generator_ids] for i in range(len(group))]
    images = []
    for assignment in product(*choices):
        image_ids = [group_ids[g] for g in assignment]
        mapping, used, queue = {0: 0}, {0}, [0]
        valid = True
        for g in queue:
            for k, image in enumerate(image_ids):
                h = source_products[g][k]
                mapped = multiply(mapping[g], image)
                if h in mapping:
                    if mapping[h] != mapped:
                        valid = False
                        break
                elif mapped in used:
                    valid = False
                    break
                else:
                    mapping[h] = mapped
                    used.add(mapped)
                    queue.append(h)
            if not valid:
                break
        if valid and len(mapping) == len(group) and all(signatures[group[g]] == signatures[group[mapping[g]]] for g in range(len(group))):
            images.append(list(assignment))
    return generators, images, count


def _outer_representatives(group, generators, images):
    """Quotient candidate automorphisms by known, integrally realized inner ones."""
    sp = _sp()
    d = len(group[0])
    keys = [tuple(int(x) for row in g for x in row) for g in group]
    ids = {key: i for i, key in enumerate(keys)}
    inverses = [tuple(int(x) for x in sp.Matrix(g).inv()) for g in group]
    def multiply(a, b):
        return tuple(sum(a[i*d+k]*b[k*d+j] for k in range(d)) for i in range(d) for j in range(d))
    source = tuple(ids[tuple(int(x) for row in g for x in row)] for g in generators)
    covered, representatives = set(), []
    ordered = [generators]+[image for image in images if image != generators]
    for assignment in ordered:
        key = tuple(ids[tuple(int(x) for row in g for x in row)] for g in assignment)
        if key in covered:
            continue
        orbit = {tuple(ids[multiply(multiply(h, keys[j]), hi)] for j in key) for h, hi in zip(keys, inverses)}
        covered.update(orbit)
        representatives.append((assignment, len(orbit), source in orbit))
    if len(covered) != len(images):
        raise ArithmeticError("Inner-automorphism cosets failed finite exhaustion")
    return representatives


def split_centralizer(group, decomposition=None, max_trials=2000,
                      max_orbit=20000, max_generators=100000):
    sp = _sp()
    decomposition = decomposition or split_decomposition(group, max_trials)
    if decomposition is None:
        return None
    projections = projection_lattice_basis(decomposition["basis"], decomposition["components"])
    orbit = lattice_orbit_transport(projections["lattice"], None, projections["ambientGenerators"], max_orbit, max_generators)
    basis = projections["basis"]
    inverse = basis.inv()
    generators = [basis*g*inverse for g in orbit["generators"]]
    if any(any(x.q != 1 for x in g) or abs(g.det()) != 1 for g in generators):
        raise ArithmeticError("Arithmetic stabilizer failed integer unimodularity")
    finite = all(p["multiplicity"] == 1 for p in decomposition["components"])
    full_order = 2**len(decomposition["components"])//orbit["orbitSize"] if finite else None
    return {"complete": True, "unitGroupComplete": True, "finite": finite,
            "centralizerOrder": full_order, "generators": [c._from_sympy(g) for g in generators],
            "algorithm": "split-rational-projection-lattice-schreier",
            "latticeOrbitSize": orbit["orbitSize"],
            "ambientLatticeIndex": abs(int(projections["lattice"].det())),
            "rationalTensorBasis": c._from_sympy(decomposition["basis"]),
            "projectionOverlatticeBasis": c._from_sympy(basis),
            "splitComponents": [{"irreducibleDimension": p["irreducibleDimension"], "multiplicity": p["multiplicity"]} for p in decomposition["components"]],
            "certificate": "Every rational centralizer acts on multiplicity coordinates; sums of all coordinate projections give intrinsic multiplicity lattices; full GL(m,Z) acts on their product; exhaustive finite fixed-index lattice orbit and Schreier stabilizer recover every integral unit"}


def definite_units(group, basis=None, max_vectors=2000000):
    """All units when the adjoint norm is a scalar positive quadratic form.

    Covers definite quaternion orders as well as imaginary quadratic and real
    scalar orders, without recognizing a named maximal order or a lookup table.
    """
    sp = _sp()
    d = len(group[0])
    point_generators = [c._sympy_matrix(g) for g in ext._choose_generators(group)] or [sp.eye(d)]
    basis = basis or commutant_basis(point_generators)
    gram = c._sympy_matrix(c.invariant_gram(group))
    adjoints = [gram.inv()*a.T*gram for a in basis]
    q = sp.zeros(len(basis))
    for i, a in enumerate(basis):
        for j, b in enumerate(basis):
            value = (adjoints[i]*b+adjoints[j]*a)/2
            scalar = sp.trace(value)/d
            if value != scalar*sp.eye(d):
                return None
            q[i, j] = scalar
    if any(q[:k, :k].det() <= 0 for k in range(1, q.rows+1)):
        return None
    inverse = q.inv()
    limits = [isqrt(int(inverse[i, i].p)//int(inverse[i, i].q)) for i in range(q.rows)]
    candidates = prod(2*b+1 for b in limits)
    if candidates > max_vectors:
        raise c.SearchLimitError("Definite order norm-one enumeration exceeds max_vectors")
    units, coefficients = [], []
    for values in product(*(range(-b, b+1) for b in limits)):
        v = sp.Matrix(values)
        if (v.T*q*v)[0] != 1:
            continue
        a = sum((x*b for x, b in zip(values, basis)), sp.zeros(d))
        if abs(a.det()) != 1:
            raise ArithmeticError("A scalar adjoint norm-one integer element failed unit verification")
        units.append(c._from_sympy(a))
        coefficients.append(list(values))
    eye = c.identity(d)
    units = [eye]+sorted(set(units)-{eye})
    return {"complete": True, "unitGroupComplete": True, "finite": True,
            "centralizerOrder": len(units), "generators": ext._choose_generators(units),
            "algorithm": "definite-order-adjoint-norm",
            "adjointNormMatrix": c._from_sympy(q), "unitCoefficientVectors": coefficients,
            "normVectorsTested": candidates,
            "quaternionOrderCertified": len(basis) == 4 and d == 4,
            "certificate": "Verified adjoint identity a* a = q(a) I on the entire saturated integer order; positive quadratic q and determinant +-1 force q=1; every integer norm-one vector enumerated with rigorous inverse-form bounds"}


def _quadratic_sign(a, b, discriminant):
    """Sign of a+b*sqrt(discriminant), using integers only."""
    if b == 0:
        return (a > 0)-(a < 0)
    if a == 0 or (a > 0) == (b > 0):
        return (b > 0)-(b < 0)
    difference = a*a-discriminant*b*b
    return ((difference > 0)-(difference < 0))*((a > 0)-(a < 0))


def quadratic_order_units(group, basis=None, max_pell_steps=10000,
                          max_unit_candidates=100000):
    """Complete unit group of any real quadratic commutant order.

    No maximal-order assumption: the primitive basis {1,T} and its actual order
    discriminant determine the necessary parity congruence. Continued fractions
    provide a rigorous finite search bound and exact inequalities identify the
    fundamental unit, including norm -1 units.
    """
    sp = _sp()
    d = len(group[0])
    basis = basis or commutant_basis([c._sympy_matrix(g) for g in ext._choose_generators(group)] or [sp.eye(d)])
    if len(basis) != 2 or basis[0]*basis[1] != basis[1]*basis[0]:
        return None
    identity = sp.eye(d)
    coefficients = _coordinates(basis, identity)
    if any(x.q != 1 for x in coefficients):
        raise ArithmeticError("Identity is not in the integer commutant order")
    u, v, divisor = sp.gcdex(int(coefficients[0]), int(coefficients[1]))
    if abs(divisor) != 1:
        raise ArithmeticError("Identity is not primitive in the saturated integer order")
    if divisor == -1:
        u, v = -u, -v
    t_matrix = -v*basis[0]+u*basis[1]
    trace = 2*sp.trace(t_matrix)/d
    field_norm = (trace**2-2*sp.trace(t_matrix*t_matrix)/d)/2
    if trace.q != 1 or field_norm.q != 1 or t_matrix*t_matrix-trace*t_matrix+field_norm*identity != sp.zeros(d):
        return None
    trace, field_norm = int(trace), int(field_norm)
    discriminant = trace*trace-4*field_norm
    if discriminant <= 0 or isqrt(discriminant)**2 == discriminant:
        return None
    if discriminant < 5 or discriminant % 4 not in (0, 1):
        raise ArithmeticError("Invalid real quadratic order discriminant")
    # Continued fraction of sqrt(D), convergents p/q, until the Pell +1 unit.
    a0 = isqrt(discriminant)
    m, denominator, a = 0, 1, a0
    p_old, p_older, q_old, q_older = 1, 0, 0, 1
    for steps in range(1, max_pell_steps+1):
        p, q = a*p_old+p_older, a*q_old+q_older
        if p*p-discriminant*q*q == 1:
            break
        p_older, p_old, q_older, q_old = p_old, p, q_old, q
        m = denominator*a-m
        denominator = (discriminant-m*m)//denominator
        a = (a0+m)//denominator
    else:
        raise c.SearchLimitError("Pell continued-fraction certificate exceeded max_pell_steps")
    coefficient_bound = 2*q
    chosen = None
    for b in range(1, coefficient_bound+1):
        if b > max_unit_candidates:
            raise c.SearchLimitError("Fundamental quadratic unit search exceeded max_unit_candidates; the full unit group is not established")
        for unit_norm in (-1, 1):
            square = discriminant*b*b+4*unit_norm
            if square < 0:
                continue
            x = isqrt(square)
            if x*x != square or (x-trace*b) % 2 or _quadratic_sign(x-2, b, discriminant) <= 0:
                continue
            candidate = (x, b, unit_norm)
            if chosen is None or _quadratic_sign(x-chosen[0], b-chosen[1], discriminant) < 0:
                chosen = candidate
        if chosen is not None:
            # Units with this b lie in (b sqrt(D)-1,b sqrt(D)+1). Since
            # D>=5 these intervals are disjoint and increasing for distinct b.
            # All smaller coefficients have been exhausted, so this is the
            # least positive unit >1, not merely a Pell solution.
            break
    if chosen is None:
        raise ArithmeticError("Pell certificate supplied no unit in the original quadratic order")
    x, b, unit_norm = chosen
    a = (x-trace*b)//2
    unit = a*identity+b*t_matrix
    if any(z.q != 1 for z in unit) or abs(unit.det()) != 1 or a*a+trace*a*b+field_norm*b*b != unit_norm:
        raise ArithmeticError("Fundamental quadratic unit failed its exact norm certificate")
    return {"complete": True, "unitGroupComplete": True, "finite": False,
            "centralizerOrder": None, "generators": [c._from_sympy(-identity), c._from_sympy(unit)],
            "algorithm": "quadratic-order-pell-units", "orderDiscriminant": discriminant,
            "quadraticOrderGenerator": c._from_sympy(t_matrix),
            "quadraticOrderPolynomial": f"x**2 - ({trace})*x + ({field_norm})",
            "fundamentalUnitCoefficients": [a, b], "fundamentalUnitFieldNorm": unit_norm,
            "fundamentalUnitRadical": {"rationalNumerator": x, "radicalNumerator": b,
                                       "discriminant": discriminant, "denominator": 2},
            "pellCertificate": {"p": p, "q": q, "steps": steps,
                                "coefficientBound": coefficient_bound, "coefficientsChecked": b},
            "certificate": "Primitive integer order basis {1,T}; exact order discriminant and parity; continued fractions give p²-Dq²=1 and a finite coefficient bound; exhaustive smaller coefficients and exact radical comparison prove the least unit >1; all units are generated by this fundamental unit and -1"}


def quadratic_integral_equivalence(left_generators, right_generators,
                                   max_candidates=100000):
    """Complete integral intertwiner decision for real quadratic commutants.

    The fundamental source unit preserves the saturated integer Hom lattice.
    Reducing its two real embeddings bounds a representative of every possible
    unimodular Hom orbit inside an explicit finite coefficient box.
    """
    sp = _sp()
    left = [c._sympy_matrix(c.matrix(g)) for g in left_generators]
    right = [c._sympy_matrix(c.matrix(g)) for g in right_generators]
    source_group = ext._point_input({"rotations": left_generators})
    units = quadratic_order_units(source_group)
    if units is None:
        return None
    hom = intertwiner_basis(left, right, integral=True)
    if len(hom) != 2:
        return {"complete": True, "equivalent": False, "conjugator": None,
                "certificate": "Exact Hom dimension excludes equivalence of real quadratic simple modules"}
    u, v = sp.symbols("u v")
    polynomial = (u*hom[0]+v*hom[1]).det(method="domain-ge")
    coefficient, factors = sp.factor_list(polynomial, u, v)
    if len(factors) != 1 or sp.Poly(factors[0][0], u, v).total_degree() != 2:
        raise ArithmeticError("Real quadratic intertwiner determinant has unexpected factorization")
    if abs(coefficient) != 1:
        return {"complete": True, "equivalent": False, "conjugator": None,
                "certificate": "The primitive integral Hom determinant polynomial has a nonunit fixed divisor"}
    quadratic = sp.Poly(factors[0][0], u, v)
    A, B, C = (int(quadratic.coeff_monomial(m)) for m in (u*u, u*v, v*v))
    discriminant = B*B-4*A*C
    if A == 0 or discriminant <= 0 or isqrt(discriminant)**2 == discriminant:
        raise ArithmeticError("Intertwiner norm is not a real quadratic field norm")
    unit = c._sympy_matrix(units["generators"][1])
    vectors = sp.Matrix.hstack(*(_vec(h) for h in hom))
    inverse = (vectors.T*vectors).inv()*vectors.T
    action = sp.Matrix.hstack(*(inverse*_vec(h*unit) for h in hom))
    if any(x.q != 1 for x in action) or abs(action.det()) != 1:
        raise ArithmeticError("Fundamental unit does not preserve the saturated integer Hom lattice")
    change = sp.Matrix([[2*A, B], [0, 1]])
    norm_action = change*action*change.inv()
    if norm_action[0, 0] != norm_action[1, 1] or norm_action[0, 1] != discriminant*norm_action[1, 0]:
        raise ArithmeticError("Fundamental unit is not multiplication on the quadratic Hom norm")
    # Unit eigenvalue lambda>1 is at most |trace(action)|+1. For norm S,
    # reduction gives sqrt(|S|)<=|X+Ysqrt(D)|<lambda sqrt(|S|), and the
    # conjugate absolute value <=sqrt(|S|). Use conservative integer ceilings.
    root_S = isqrt(4*abs(A))
    if root_S*root_S < 4*abs(A):
        root_S += 1
    numerator = (abs(int(sp.trace(action)))+2)*root_S
    bound_x = (numerator+1)//2
    divisor_y = 2*isqrt(discriminant)
    bound_v = (numerator+divisor_y-1)//divisor_y
    divisor_u = 2*abs(A)
    bound_u = (bound_x+abs(B)*bound_v+divisor_u-1)//divisor_u
    candidates = (2*bound_u+1)*(2*bound_v+1)
    if candidates > max_candidates:
        raise c.SearchLimitError("Certified quadratic intertwiner fundamental-domain box exceeds max_candidates")
    for a in range(-bound_u, bound_u+1):
        for b in range(-bound_v, bound_v+1):
            if abs(A*a*a+B*a*b+C*b*b) != 1:
                continue
            witness = a*hom[0]+b*hom[1]
            if abs(witness.det()) != 1 or any(witness*x != y*witness for x, y in zip(left, right)):
                raise ArithmeticError("Quadratic integral intertwiner failed exact verification")
            return {"complete": True, "equivalent": True, "conjugator": c._from_sympy(witness),
                    "coefficientBounds": [bound_u, bound_v], "candidatesBound": candidates,
                    "algorithm": "quadratic-unit-fundamental-domain",
                    "certificate": "Exact integral Hom lattice and a unimodular intertwiner verified"}
    return {"complete": True, "equivalent": False, "conjugator": None,
            "coefficientBounds": [bound_u, bound_v], "candidatesChecked": candidates,
            "algorithm": "quadratic-unit-fundamental-domain",
            "certificate": "Fundamental quadratic unit preserves the entire integer Hom lattice; every possible determinant-one intertwiner orbit has a representative inside the explicit real-embedding reduction box, which was exhaustively enumerated"}


def _centralizer_from_normalizer(group, normalizer, max_orbit=20000,
                                 max_generators=100000):
    sp = _sp()
    d = len(group[0])
    point_generators = ext._choose_generators(group) or [group[0]]
    original = tuple(tuple(c._sympy_matrix(g)) for g in point_generators)
    matrices = [(c._sympy_matrix(a), c._sympy_matrix(a).inv()) for a in normalizer["generators"]]
    states, seen = [(original, sp.eye(d))], {original: 0}
    inverses, result, known = [sp.eye(d)], [], set()
    for point_tuple, word in states:
        points = [sp.Matrix(d, d, values) for values in point_tuple]
        for a, ai in matrices:
            target = tuple(tuple(a*g*ai) for g in points)
            new_word = a*word
            norm._entry_limit(new_word)
            if target not in seen:
                if len(states) >= max_orbit:
                    raise c.SearchLimitError("Finite normalizer-to-centralizer Schreier orbit exceeds max_orbit")
                seen[target] = len(states)
                states.append((target, new_word))
                inverses.append(new_word.inv())
                continue
            unit = inverses[seen[target]]*new_word
            if unit != sp.eye(d) and tuple(unit) not in known:
                if len(result) >= max_generators:
                    raise c.SearchLimitError("Centralizer Schreier generator count exceeds max_matrices")
                result.append(c._from_sympy(unit))
                known.add(tuple(unit))
    finite = normalizer["finite"]
    order = normalizer.get("normalizerOrder")
    return {"complete": normalizer["complete"], "unitGroupComplete": normalizer["complete"],
            "finite": finite, "centralizerOrder": order//len(states) if order is not None else None,
            "generators": result, "algorithm": "normalizer-action-kernel-schreier",
            "normalizerAutomorphismImageOrder": len(states),
            "normalizerCertificate": normalizer,
            "certificate": "Exhausted the conjugation orbit of the ordered point generators; its Schreier stabilizer is exactly the centralizer inside the supplied certified normalizer",
            "scope": "Full integral centralizer" if normalizer["complete"] else "Centralizer inside the known normalizer subgroup; full arithmetic unit group is not established"}


def _component_centralizer(group, center, payload):
    sp = _sp()
    if len(center["components"]) <= 1:
        return None
    d = len(group[0])
    total_basis = sp.Matrix.hstack(*(p["basis"] for p in center["components"]))
    ambient, results, start = [], [], 0
    for piece in center["components"]:
        b = piece["basis"]
        left = (b.T*b).inv()*b.T
        local = {c._from_sympy(left*c._sympy_matrix(g)*b) for g in group}
        identity = c.identity(b.cols)
        local_group = [identity]+sorted(local-{identity})
        result = centralizer(local_group, payload)
        if not result["complete"]:
            return None
        ambient += [norm._embed(c._sympy_matrix(g), start, d) for g in result["generators"]]
        results.append(result)
        start += b.cols
    stabilizer = norm.lattice_stabilizer(total_basis, ambient,
        ext._limit(payload, "max_orbit", 20000, 100000), ext._limit(payload, "max_matrices", 100000, 100000))
    finite = all(p["finite"] for p in results)
    return {**stabilizer, "complete": True, "unitGroupComplete": True, "finite": finite,
            "centralizerOrder": prod(p["centralizerOrder"] for p in results)//stabilizer["latticeOrbitSize"] if finite else None,
            "algorithm": "central-idempotent-glue-schreier", "componentCentralizers": results,
            "certificate": "Centralizer preserves each primitive rational central component and its saturated lattice; complete component unit groups form the direct-sum overgroup; finite glue-lattice Schreier stabilizer gives all original-lattice units"}


def split_normalizer(group, payload=None, decomposition=None):
    """Full normalizer for split-rational modules, including arbitrary glue."""
    payload = payload or {}
    decomposition = decomposition or split_decomposition(group, ext._limit(payload, "max_trials", 2000, 100000))
    if decomposition is None:
        return None
    units = split_centralizer(group, decomposition,
        max_orbit=ext._limit(payload, "max_orbit", 20000, 100000),
        max_generators=ext._limit(payload, "max_matrices", 100000, 100000))
    generators, images, assignments = automorphism_images(group, ext._limit(payload, "max_assignments", 100000, 2000000))
    output = list(units["generators"])+list(generators)
    realized = 0
    representatives = _outer_representatives(group, generators, images)
    for target, coset_size, inner in representatives:
        if inner:
            realized += coset_size
            continue
        equivalence = labelled_integral_equivalence(generators, target, decomposition=decomposition,
            max_orbit=ext._limit(payload, "max_orbit", 20000, 100000),
            max_generators=ext._limit(payload, "max_matrices", 100000, 100000))
        if not equivalence["complete"]:
            raise ArithmeticError("Verified split module lost its equivalence certificate")
        if equivalence["equivalent"]:
            realized += coset_size
            output.append(equivalence["conjugator"])
    finite = units["finite"]
    return {"complete": True, "finite": finite,
            "normalizerOrder": units["centralizerOrder"]*realized if finite else None,
            "generators": [c._from_sympy(a) for a in norm._deduplicate([c._sympy_matrix(g) for g in output])],
            "algorithm": "split-rational-arithmetic-normalizer",
            "centralizer": units, "rationalAutomorphismCount": len(images),
            "integralAutomorphismCount": realized, "outerCosetsChecked": len(representatives), "automorphismAssignmentsChecked": assignments,
            "certificate": "Complete arithmetic centralizer; every character-preserving abstract automorphism exhaustively generated from Cayley relations; each integral lift decided by exact finite projection-lattice transport; one lift per realizable coset plus the full centralizer generates the normalizer",
            "scope": "Full integral normalizer of this split-rational finite-group representation"}


def centralizer(group, payload=None, center=None):
    payload = payload or {}
    sp = _sp()
    if center is None:
        basis = commutant_basis([c._sympy_matrix(g) for g in ext._choose_generators(group)] or [sp.eye(len(group[0]))])
        center = center_decomposition(basis)
    decomposition = split_decomposition(group, ext._limit(payload, "max_trials", 2000, 100000), center)
    result = split_centralizer(group, decomposition,
        max_orbit=ext._limit(payload, "max_orbit", 20000, 100000),
        max_generators=ext._limit(payload, "max_matrices", 100000, 100000)) if decomposition is not None else None
    if result is None:
        result = definite_units(group, max_vectors=ext._limit(payload, "max_vectors", 2000000, 10000000))
    if result is None:
        result = quadratic_order_units(group,
            max_pell_steps=ext._limit(payload, "max_pell_steps", 10000, 100000),
            max_unit_candidates=ext._limit(payload, "max_unit_candidates", 100000, 2000000))
    if result is None:
        result = _component_centralizer(group, center, payload)
    if result is None:
        known = norm.normalizer(group,
            max_vectors=ext._limit(payload, "max_vectors", 2000000, 10000000),
            max_matrices=ext._limit(payload, "max_matrices", 100000, 100000),
            max_orbit=ext._limit(payload, "max_orbit", 20000, 100000),
            max_module_trials=ext._limit(payload, "max_module_trials", 20000, 100000),
            max_point_orbit=ext._limit(payload, "max_point_orbit", 64, 2000))
        result = _centralizer_from_normalizer(group, known,
            ext._limit(payload, "max_orbit", 20000, 100000), ext._limit(payload, "max_matrices", 100000, 100000))
    point_generators = ext._choose_generators(group)
    for a in result["generators"]:
        if abs(c.determinant(a)) != 1 or any(c.matmul(a, g) != c.matmul(g, a) for g in point_generators):
            raise ArithmeticError("Arithmetic centralizer generator failed exact verification")
    result["everyGeneratorVerified"] = True
    if not result["complete"]:
        result["remainingObstacle"] = "The full unit group of this non-split arithmetic order has not been established by the available certified branches"
    return result


def arithmetic_normalizer(group, payload=None):
    payload = payload or {}
    def verified(result):
        point_generators = [c._sympy_matrix(g) for g in ext._choose_generators(group)]
        group_set = {tuple(c._sympy_matrix(g)) for g in group}
        for raw in result["generators"]:
            a = c._sympy_matrix(raw)
            if any(x.q != 1 for x in a) or abs(a.det()) != 1:
                raise ArithmeticError("Arithmetic normalizer generator is not integral unimodular")
            inverse = a.inv()
            if any(tuple(inverse*g*a) not in group_set for g in point_generators):
                raise ArithmeticError("Arithmetic normalizer generator failed exact conjugation verification")
        result["everyGeneratorVerified"] = True
        result["generatorCount"] = len(result["generators"])
        return result
    def legacy():
        return verified(norm.normalizer(group,
            max_vectors=ext._limit(payload, "max_vectors", 2000000, 10000000),
            max_matrices=ext._limit(payload, "max_matrices", 100000, 100000),
            max_orbit=ext._limit(payload, "max_orbit", 20000, 100000),
            max_module_trials=ext._limit(payload, "max_module_trials", 20000, 100000),
            max_point_orbit=ext._limit(payload, "max_point_orbit", 64, 2000),
            tensor_basis=payload.get("tensor_basis")))
    # Avoid huge Aut((C2)^r) enumerations and avoid sending infinite quadratic
    # centralizers into an unrelated finite-metric search before their proof.
    if norm.character_decomposition(group) is not None or norm._cyclic_generator(group) is not None:
        return legacy()
    split = split_normalizer(group, payload)
    if split is not None:
        return verified(split)
    units = quadratic_order_units(group,
        max_pell_steps=ext._limit(payload, "max_pell_steps", 10000, 100000),
        max_unit_candidates=ext._limit(payload, "max_unit_candidates", 100000, 2000000))
    if units is None:
        return legacy()
    generators, images, assignments = automorphism_images(group, ext._limit(payload, "max_assignments", 100000, 2000000))
    output, realized = list(units["generators"])+list(generators), 0
    representatives = _outer_representatives(group, generators, images)
    for target, coset_size, inner in representatives:
        if inner:
            realized += coset_size
            continue
        decision = quadratic_integral_equivalence(generators, target,
            ext._limit(payload, "max_candidates", 100000, 2000000))
        if decision is None or not decision["complete"]:
            raise ArithmeticError("Quadratic arithmetic normalizer lost its equivalence certificate")
        if decision["equivalent"]:
            output.append(decision["conjugator"])
            realized += coset_size
    return verified({"complete": True, "finite": False, "normalizerOrder": None,
            "generators": [c._from_sympy(a) for a in norm._deduplicate([c._sympy_matrix(g) for g in output])],
            "algorithm": "quadratic-order-arithmetic-normalizer", "centralizer": units,
            "rationalAutomorphismCount": len(images), "integralAutomorphismCount": realized,
            "automorphismAssignmentsChecked": assignments, "outerCosetsChecked": len(representatives),
            "certificate": "Complete real quadratic order unit group; every character-preserving point-group automorphism considered; each integral lift decided by an exhaustive fundamental-unit reduction box; centralizer plus all realizable lifts generate the full integral normalizer",
            "scope": "Full integral normalizer of this real quadratic commutant representation"})


def run(payload, database=None):
    if not isinstance(payload, dict):
        raise ValueError("Arithmetic input must be a JSON object")
    action = payload.get("action", "order")
    if action not in ("order", "centralizer", "normalizer"):
        raise ValueError("Unknown arithmetic-centralizer action")
    group = ext._point_input(payload, database)
    result, basis, center = order_data(group, payload.get("include_structure", True), payload.get("expand_norm", False))
    if action == "order":
        result.update({"complete": True, "unitGroupComplete": False,
                       "scope": "Complete integral commutant order and rational center; unit equation specified, unit-group generation not requested"})
    else:
        result.update(centralizer(group, payload, center) if action == "centralizer" else arithmetic_normalizer(group, payload))
        point_generators = ext._choose_generators(group)
        group_set = set(group)
        for a in result["generators"]:
            inverse = c._from_sympy(c._sympy_matrix(a).inv())
            if abs(c.determinant(a)) != 1 or any(c.matmul(c.matmul(inverse, g), a) not in group_set for g in point_generators):
                raise ArithmeticError("Arithmetic output failed exact unimodular normalizer verification")
        result["everyGeneratorVerified"] = True
        result["generatorCount"] = len(result["generators"])
    return c.jsonable({"action": action, **result})
